 stoneTexture(){const canvas=document.createElement('canvas');canvas.width=canvas.height=256;const ctx=canvas.getContext('2d'),img=ctx.createImageData(256,256);let seed=76;for(let y=0;y<256;y++)for(let x=0;x<256;x++){seed=(seed*1664525+1013904223)>>>0;const wave=Math.sin(x*.032+y*.018+Math.sin(y*.025)*1.5),vein=Math.pow(Math.abs(wave),18);const v=205+seed%23+vein*20;const k=(y*256+x)*4;img.data[k]=img.data[k+1]=img.data[k+2]=v;img.data[k+3]=255;}ctx.putImageData(img,0,0);const t=new THREE.CanvasTexture(canvas);t.colorSpace=THREE.SRGBColorSpace;t.wrapS=t.wrapT=THREE.RepeatWrapping;return t;}
